import re

def parse_duration(s):
    """Parse a duration string into a number of seconds."""
    total_seconds = 0

    # Find all matches of number + unit, ensuring the number is a complete token
    matches = re.findall(r'(?<!\d)(\d+)([smh])(?!\d)', s)

    for number, unit in matches:
        value = int(number)
        if unit == 's':
            total_seconds += value
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 'h':
            total_seconds += value * 3600

    # Find all bare numbers (not followed by s, m, or h)
    bare_numbers = re.findall(r'(?<!\d)(\d+)(?![smh])', s)
    for num in bare_numbers:
        total_seconds += int(num)

    return total_seconds

