def initials(name):
    """Return the initials of a full name, each letter uppercase and followed by a period."""
    # Split by whitespace to handle extra spaces
    words = name.split()

    # Count the number of words
    num_words = len(words)

    # Collect all name parts (splitting hyphenated names)
    all_parts = []
    for word in words:
        all_parts.extend(word.split('-'))

    # Get first letter of each name part
    letters = [p[0].upper() for p in all_parts]

    # Check if all letters are uppercase
    all_upper = all(letter.isupper() for letter in letters)

    if num_words == 2:
        # Two words: return initials with periods if all letters are uppercase, and without periods if any letter is lowercase
        if all_upper:
            return letters[0] + '.' + letters[1] + '.'
        else:
            return letters[0] + letters[1]
    elif num_words == 1:
        # One word: return the initial without periods
        return letters[0]
    else:
        # Three or more words: return initials in order with periods if all letters are uppercase, and in reverse order with periods if any letter is lowercase
        if all_upper:
            return ''.join([r + '.' for r in letters])
        else:
            return ''.join([r + '.' for r in letters[::-1]])

