def median(xs):
    # Filter out None values
    filtered = [x for x in xs if x is not None]

    # Empty list after filtering
    if len(filtered) == 0:
        return None

    # Sort the list
    filtered.sort()

    n = len(filtered)

    # Odd length: return the lower middle value
    if n % 2 == 1:
        return filtered[(n - 1) // 2]
    else:
        # Even length: return the larger of the two middle values
        return max(filtered[n // 2 - 1], filtered[n // 2])

