def clamp(x, lo, hi):
    # If lo > hi, swap them
    if lo is not None and lo > hi:
        lo, hi = hi, lo

    result = x

    # Apply lower bound if it exists
    if lo is not None:
        result = max(result, lo)

    # Apply upper bound if it exists
    if hi is not None:
        result = min(result, hi)

    return result

